package org.jsoup.helper;

import org.junit.Test;
import org.jsoup.Connection;
import static org.junit.Assert.*;

import java.net.MalformedURLException;
import java.net.URL;
import java.io.UnsupportedEncodingException;

public class UrlBuilderTest {

    @Test
    public void UrlBuilderConstructorTest() {
        try {
            URL inputUrl = new URL("http://www.example.com");
            UrlBuilder builder = new UrlBuilder(inputUrl);
            assertNotNull(builder);
        } catch (MalformedURLException e) {
            e.printStackTrace();
        }
    }

    @Test(expected = MalformedURLException.class)
    public void UrlBuilderConstructorExceptionTest() throws MalformedURLException {
        URL inputUrl = new URL("invalid");
        UrlBuilder builder = new UrlBuilder(inputUrl);
    }

    @Test
    public void buildTest() {
        try {
            URL inputUrl = new URL("http://www.example.com");
            UrlBuilder builder = new UrlBuilder(inputUrl);
            URL outputUrl = builder.build();
            assertEquals(outputUrl, inputUrl);
        } catch (MalformedURLException e) {
            e.printStackTrace();
        }
    }

    @Test
    public void appendKeyValTest() {
        try {
            URL inputUrl = new URL("http://www.example.com");
            UrlBuilder builder = new UrlBuilder(inputUrl);
            Connection.KeyVal kv = Connection.KeyVal.create("key", "value");
            builder.appendKeyVal(kv);
            URL outputUrl = builder.build();
            assertTrue("URL does not contain appended parameters", outputUrl.toString().contains("key=value"));
        } catch (MalformedURLException | UnsupportedEncodingException e) {
            e.printStackTrace();
        }
    }

    @Test(expected = UnsupportedEncodingException.class)
    public void appendKeyValExceptionTest() throws MalformedURLException, UnsupportedEncodingException {
        URL inputUrl = new URL("http://www.example.com");
        UrlBuilder builder = new UrlBuilder(inputUrl);
        Connection.KeyVal kv = Connection.KeyVal.create("key", "测\u0080"); // create an invalid encoding
        builder.appendKeyVal(kv);
    }
}
